insert into qa_message (
    project_id, session_id, role, question, answer, route_mode, references_json, usage_json, retrieval_diagnostics_json,
    feedback_json, status, task_id, request_json, error_message, created_by, updated_by
) values (
    #{projectId}, #{sessionId}, #{role}, #{question}, #{answer}, #{routeMode}, #{referencesJson}, #{usageJson}, #{retrievalDiagnosticsJson},
    #{feedbackJson}, #{status}, #{taskId}, #{requestJson}, #{errorMessage}, #{createdBy}, #{updatedBy}
