mapper.update:
update qa_message
set task_id = #{taskId},
    updated_by = #{updatedBy}
where id = #{messageId}
  and status = 'PENDING'
  and deleted = 0

update qa_message
set status = 'PROCESSING',
    error_message = null,
    updated_by = #{updatedBy}
where id = #{messageId}
  and task_id = #{taskId}
  and status in ('PENDING', 'PROCESSING', 'FAILED')
  and deleted = 0

update qa_message
set status = 'FAILED',
    error_message = #{errorMessage},
    retrieval_diagnostics_json = #{retrievalDiagnosticsJson},
    updated_by = #{updatedBy}
where id = #{messageId}
  and task_id = #{taskId}
  and status in ('PENDING', 'PROCESSING')
  and deleted = 0

