select 
from (
    select 
    from qa_message
    where session_id = #{sessionId}
      and id < #{beforeMessageId}
      and status = 'SUCCESS'
      and deleted = 0
    order by created_at desc, id desc
    limit #{limit}
) latest
order by created_at asc, id asc

mapper.update:
update qa_message
set feedback_json = #{feedbackJson},
    updated_by = #{updatedBy}
where id = #{messageId}
  and deleted = 0
